const s = $input.first().json;
const actual = s.actual || {};
const expected = s.expected || {};
const diff = [];
for (const k of Object.keys(expected)) {
  if (JSON.stringify(expected[k]) !== JSON.stringify(actual[k])) diff.push({field:k, expected:expected[k], actual:actual[k]});
}
const taxonomy = diff.map(d=>({code:"trace_mismatch", severity:"high", detail:`${d.field}: expected ${JSON.stringify(d.expected)} got ${JSON.stringify(d.actual)}`}));
return [{json:{scenario_id:s.scenario_id, pipeline:"observatory", verdict: diff.length?"fail":"pass", differences: diff, failure_taxonomy: taxonomy}}];

